const GCOL=["var(--verd)","var(--gold)","#c9a1e8","#e39a6b"];
function ensureGroups(){const st=ST();
  if(!st.groups||!st.groups.length){st.groups=[{id:"g1",name:"Groupe 1",col:0,scene:st.scene}];st.active="g1";}
  if(!st.groups.some(g=>g.id===st.active))st.active=st.groups[0].id;
  st.party.forEach(p=>{if(!st.groups.some(g=>g.id===p.grp))p.grp=st.groups[0].id;});}
