  const hurt=st.party.filter(p=>{const c=charById(p.cid);return c&&(p.state!=="ok"||p.pv<=Math.ceil(c.pv/2));}).map(p=>`${esc(charById(p.cid).n.split(" ")[0])} ${p.state!=="ok"?STATES.find(x=>x[0]===p.state)[1].toLowerCase():p.pv+" PV"}`);
