function startAmb(id){ac();if(SND.amb[id]||!REC_AMB[id])return;const C=SND.ctx,R=REC_AMB[id],vol=S.snd.vols[id]??.7;
  const A={on:true,out:gn(0),srcs:[],lfos:[],loop(fn,min,max,late){const t=()=>{if(!A.on)return;fn();A.h=setTimeout(t,rnd(min,max));};setTimeout(t,late?rnd(min,max):rnd(0,400));}};
  A.out.connect(SND.master);A.out.gain.setValueAtTime(0,C.currentTime);A.out.gain.linearRampToValueAtTime(vol,C.currentTime+2);
  SND.amb[id]=A;renderSnd();
  loadBuf(R.f).then(buf=>{if(!A.on)return;const s=C.createBufferSource();s.buffer=buf;s.loop=true;s.loopStart=.05;s.loopEnd=buf.duration-.05;
    s.connect(A.out);s.start(0,rnd(0,buf.duration*.8));A.srcs.push(s);
    if(R.thunder)A.loop(()=>{const w=gn(.8);w.connect(A.out);REC_FX.tonnerre.run(w);},15000,32000,true);
  }).catch(()=>{toast(`Le son « ${R.n} » n'a pas pu être chargé.`);stopAmb(id);});}
