/* ---------- Progression et historique des personnages ---------- */
if(!S.prog)S.prog={};
const P_=cid=>S.prog[cid]||(S.prog[cid]={skills:{},checks:[],hist:[]});
function carOf(c){const o=Object.assign({},c.car||{},(S.prog[c.id]&&S.prog[c.id].car)||{});if(!o.DEX&&c.dex)o.DEX=c.dex;Object.keys(o).forEach(k=>{if(!o[k])delete o[k];});return o;}
function parseSk(str){return String(str||"").split("·").map(x=>x.trim()).map(x=>{const m=x.match(/^(.+?)\s+(\d{1,2})\b/);return m?[m[1].replace(/\s+$/,""),+m[2]]:null;}).filter(Boolean);}
function skillsOf(c){const pr=S.prog[c.id];const base=parseSk(c.sk);const seen=new Set(base.map(b=>b[0]));
  const out=base.map(([n,v])=>[n,pr&&pr.skills[n]!=null?pr.skills[n]:v]);
  if(pr)Object.entries(pr.skills).forEach(([n,v])=>{if(!seen.has(n))out.push([n,v]);});return out;}
/* (comment removed) */
const WEAP_SK=[[/revolver|pistolet|arme de poing/i,"Armes de poing"],[/fusil|carabine/i,"Fusils"],[/crosse|cran d|canif|couteau|matraque|gourdin|pelle/i,"Corps à corps"]];
function allSkillsOf(c){const own=skillsOf(c);const have=new Set(own.map(x=>x[0]));const out=[];
  own.forEach(([n,v])=>{const w=WEAP_SK.find(([re])=>re.test(n));if(w&&!have.has(w[1])){have.add(w[1]);out.push([w[1],v,"arme"]);}});
  const hasTOC=[...have].some(n=>/^toc$/i.test(n));
  SKILLS.forEach(([n,b])=>{if(have.has(n)||n==="Sciences (autre)")return;if(n==="Trouver Objet Caché"&&hasTOC)return;
    let v=b;if(b==="DEX/2")v=Math.floor((carOf(c).DEX||50)/2);else if(b==="ÉDU"){v=carOf(c)["ÉDU"];if(!v)return;}
    out.push([n,v,"base"]);});
  return own.concat(out);}
const skStr=c=>{const extra=String(c.sk||"").split("·").map(x=>x.trim()).filter(x=>!/^.+?\s+\d{1,2}\b/.test(x));return skillsOf(c).map(([n,v])=>`${n} ${v}`).concat(extra).join(" · ");};
const isChecked=(cid,n)=>(S.prog[cid]?.checks||[]).includes(n);
function histAdd(cid,txt){const p=P_(cid);p.hist.unshift({at:Date.now(),txt});p.hist=p.hist.slice(0,200);}
const fmtD=t=>new Date(t).toLocaleDateString("fr-FR",{day:"numeric",month:"short",year:"numeric"});
function progHTML(c){const p=S.prog[c.id]||{checks:[],hist:[]};const sanNow=p.san??c.san;
  return `<div class="prog2">
    <div class="pr-row"><b>Santé mentale actuelle</b> <span class="pv">${sanNow}</span>${p.san!=null&&p.san!==c.san?`<span class="mut">(départ ${c.san})</span>`:""}
      <button class="mini-b" data-psan="${c.id}" data-d="-1" aria-label="SAN −1">−</button><button class="mini-b" data-psan="${c.id}" data-d="1" aria-label="SAN +1">+</button></div>
    <div class="pr-row"><b>Phase d'amélioration</b> ${p.checks.length?`<span class="mut">${p.checks.map(esc).join(", ")}</span><button class="btn prim" data-improve="${c.id}">Lancer les jets</button>`:`<span class="mut">aucune compétence cochée. Coche-les pendant la partie depuis sa fiche.</span>`}</div>
    <div id="impres-${c.id}"></div>
    <div class="pr-row"><b>Historique</b><input id="hn-${c.id}" class="hin" placeholder="Ajouter une note (cicatrice, phobie, objet trouvé…)"><button class="btn" data-hadd="${c.id}">Ajouter</button></div>
    ${p.hist&&p.hist.length?`<ol class="hist">${p.hist.map(x=>`<li><span class="hd">${fmtD(x.at)}</span>${esc(x.txt)}</li>`).join("")}</ol>`:`<p class="mut" style="margin:0">Pas encore d'histoire. Elle se remplit à la fin de chaque scénario.</p>`}
  </div>`;}
function improve(cid){const c=charById(cid),p=P_(cid),res=[];let sanGain=0;
  p.checks.forEach(n=>{const cur=(allSkillsOf(c).find(x=>x[0]===n)||[n,0])[1];const r=1+Math.floor(Math.random()*100);
    if(r>cur){const g=1+Math.floor(Math.random()*10);const nv=Math.min(99,cur+g);p.skills[n]=nv;res.push(`<li class="up">${esc(n)} : jet ${r} → <b>+${g}</b> (${cur} → ${nv})</li>`);histAdd(cid,`${n} progresse de ${cur} à ${nv}`);
}
    else res.push(`<li>${esc(n)} : jet ${r}, pas d'amélioration (${cur})</li>`);});
  if(sanGain){p.san=(p.san??c.san)+sanGain;histAdd(cid,`Maîtrise atteinte : +${sanGain} SAN`);res.push(`<li class="up">Compétence à 90 % : <b>+${sanGain} SAN</b></li>`);}
  p.checks=[];save();renderHome();
  const box=document.getElementById("impres-"+cid);if(box){box.closest("details").open=true;box.innerHTML=`<ul class="impres">${res.join("")}</ul>`;}
  toast(`${c.n} : phase d'amélioration terminée.`);}
document.addEventListener("click",e=>{
  const ck=e.target.closest("[data-chk]");if(ck){const p=P_(ck.dataset.chk),n=ck.dataset.sk;p.checks=p.checks.includes(n)?p.checks.filter(x=>x!==n):p.checks.concat(n);save();ck.classList.toggle("on");return;}
  const im=e.target.closest("[data-improve]");if(im){improve(im.dataset.improve);return;}
  const ps=e.target.closest("[data-psan]");if(ps){const c=charById(ps.dataset.psan),p=P_(c.id);p.san=Math.max(0,(p.san??c.san)+ +ps.dataset.d);save();renderHome();document.querySelector(`[data-psan="${c.id}"]`)?.closest("details")?.setAttribute("open","");return;}
  const ha=e.target.closest("[data-hadd]");if(ha){const id=ha.dataset.hadd,i=document.getElementById("hn-"+id);if(!i.value.trim())return;histAdd(id,i.value.trim());save();renderHome();document.getElementById("hn-"+id)?.closest("details")?.setAttribute("open","");}
});

