function bindFin(){$("#btnFin").onclick=()=>{$("#finZone").innerHTML=`<span class="confirm">Clore « ${esc(SC().t)} » ? <button class="btn prim" id="finYes">Oui</button><button class="btn" id="finNo">Non</button></span>`;
  $("#finYes").onclick=()=>{const st=ST();st.party.forEach(sl=>{const c=charById(sl.cid);if(!c)return;const p=P_(sl.cid);p.san=sl.san;if(sl.player)p.player=sl.player;
      histAdd(sl.cid,`A joué « ${SC().t} »${sl.player?` (joueur : ${sl.player})`:""} : PV ${sl.pv}/${c.pv}, SAN ${sl.san}${sl.state!=="ok"?`, ${STATES.find(x=>x[0]===sl.state)[1].toLowerCase()}`:""}${p.checks.length?`. ${p.checks.length} compétence(s) à améliorer`:""}`);});
    st.finished=Date.now();jlog("Scénario terminé","partie");campLog(`« ${SC().t} » terminé avec ${st.party.map(sl=>charById(sl.cid)?.n).filter(Boolean).join(", ")||"personne"}`);saveSnapshot(`Fin de partie`,true);save();show("joueurs");toast("Scénario clos. Lance la phase d'amélioration depuis la fiche de chaque personnage.");};
  $("#finNo").onclick=()=>{$("#finZone").innerHTML=`<button class="gm-item" id="btnFin">Terminer le scénario</button>`;bindFin();};};}
