/* ---------- Sauvegardes ---------- */
let DB=null,UID=null,cloudT=null,SAVES=[];
const SKEY="gardien-saves";
function localSaves(){try{return JSON.parse(localStorage.getItem(SKEY))||[];}catch(e){return [];}}
function setLocalSaves(a){try{localStorage.setItem(SKEY,JSON.stringify(a));}catch(e){}}
function saveHint(){const el=$("#saveHint");if(!el)return;el.textContent=DB?"Sauvegarde automatique sur ton compte Claude : la partie te suit d'un appareil à l'autre.":"Sauvegarde automatique dans ce navigateur.";}
function cloudPush(){if(!DB)return;clearTimeout(cloudT);cloudT=setTimeout(async()=>{try{const o={...S};delete o.log;await DB.doc(`data/users/${UID}/etat`).set({at:S.savedAt,json:JSON.stringify(o)});}catch(e){}},2500);}
async function loadSaves(){if(DB){try{const q=await DB.collection(`data/users/${UID}`).get();SAVES=q.docs.filter(d=>d.id.startsWith("save-")).map(d=>({id:d.id,...d.data()}));}catch(e){SAVES=localSaves();}}else SAVES=localSaves();
  SAVES.sort((a,b)=>b.at-a.at);if(S.view==="accueil")renderHome();}
async function saveSnapshot(name,quiet){const id="save-"+Date.now().toString(36);const o={id,name:name||"Sauvegarde",scen:S.cur,camp:S.campId,at:Date.now(),
    json:JSON.stringify({scen:S.scen[S.cur],prog:S.prog,chars:S.chars})};
  if(DB){try{await DB.doc(`data/users/${UID}/${id}`).set({name:o.name,scen:o.scen,camp:o.camp,at:o.at,json:o.json});}catch(e){const a=localSaves();a.push(o);setLocalSaves(a);}}else{const a=localSaves();a.push(o);setLocalSaves(a);}
  SAVES.unshift(o);if(!quiet)toast(`Partie sauvegardée : ${o.name}.`);}
async function delSave(id){SAVES=SAVES.filter(s=>s.id!==id);setLocalSaves(localSaves().filter(s=>s.id!==id));if(DB){try{await DB.doc(`data/users/${UID}/${id}`).delete();}catch(e){}}renderHome();}
function restoreSave(id){const s=SAVES.find(x=>x.id===id);if(!s)return;if((s.camp||"c1")!==S.campId)switchCamp(s.camp||"c1");const d=JSON.parse(s.json);S.scen[s.scen]=d.scen;if(d.prog)S.prog=d.prog;if(d.chars)S.chars=d.chars;S.cur=s.scen;save();show("jouer");toast(`Partie restaurée : ${s.name}.`);}
function bindSave(){$("#btnSave").onclick=()=>{const def=`Séance du ${new Date().toLocaleDateString("fr-FR",{day:"numeric",month:"long"})}`;
  $("#saveZone").innerHTML=`<span class="confirm"><input id="saveName" value="${esc(def)}" aria-label="Nom de la sauvegarde"><button class="btn prim" id="saveYes">Enregistrer</button></span>`;$("#saveName").select();
  const go=async()=>{await saveSnapshot($("#saveName").value.trim());$("#saveZone").innerHTML=`<button class="gm-item" id="btnSave">Sauvegarder la partie</button>`;bindSave();};
  $("#saveYes").onclick=go;$("#saveName").onkeydown=e=>{if(e.key==="Enter")go();};};}
bindSave();
function savesHTML(scid){const list=SAVES.filter(s=>s.scen===scid&&true);if(!list.length)return "";
  return `<details class="saves"><summary>${list.length} sauvegarde${list.length>1?"s":""}</summary><ul>${list.map(s=>`<li><span>${esc(s.name)} <span class="mut">· ${new Date(s.at).toLocaleString("fr-FR",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"})}</span></span>
    <span data-svz="${s.id}"><button class="btn" data-restore="${s.id}">Restaurer</button><button class="mini-b" data-sdel="${s.id}" aria-label="Supprimer">×</button></span></li>`).join("")}</ul></details>`;}
document.addEventListener("click",e=>{
  const r=e.target.closest("[data-restore]");if(r){const id=r.dataset.restore;r.parentElement.innerHTML=`<span class="confirm">Remplacer la partie en cours ? <button class="btn warn" data-restyes="${id}">Oui</button></span>`;return;}
  const ry=e.target.closest("[data-restyes]");if(ry){restoreSave(ry.dataset.restyes);return;}
  const sd=e.target.closest("[data-sdel]");if(sd){sd.parentElement.innerHTML=`<button class="btn warn" data-sdelyes="${sd.dataset.sdel}">Supprimer ?</button>`;return;}
  const sy=e.target.closest("[data-sdelyes]");if(sy){delSave(sy.dataset.sdelyes);}
});
(async()=>{try{if(!window.claude||!claude.use)return loadSaves();const [db,user]=await Promise.all([claude.use("db"),claude.use("user")]);
  if(db&&user){const id=await user.id();if(id){DB=db;UID=id;
    const snap=await DB.doc(`data/users/${UID}/etat`).get();
    if(snap.exists){const d=snap.data();if(d&&d.json&&(d.at||0)>(S.savedAt||0)){const r=JSON.parse(d.json);r.log=S.log;S=r;if(!S.prog)S.prog={};route();toast("Partie reprise depuis ton compte.");}}
    else cloudPush();}}}catch(e){}saveHint();loadSaves();})();
