/* Générateur de noms, années 1920, Nouvelle-Angleterre */
const NAMES=GRIMOIRE_DATA.NAMES;
function genNames(){const D=S.draft,o=NAMES[D.ori||"ne"],out=new Set();
  while(out.size<6){const g=D.gen==="f"||D.gen==="h"?D.gen:(Math.random()<.5?"f":"h");const p=pick(o[g]);const m=Math.random()<.35?" "+pick(o[g===g?g:"h"]).charAt(0)+".":"";out.add(`${p}${m} ${pick(o.s)}`);}
  D.nameIdeas=[...out];if(!D.nom.trim())D.nom=D.nameIdeas[0];save();renderWiz();}
$("#vCreate").addEventListener("click",e=>{if(e.target.id==="genName"){genNames();return;}const p=e.target.closest("[data-pickname]");if(p){S.draft.nom=p.dataset.pickname;save();renderWiz();}});
$("#vCreate").addEventListener("change",e=>{if(e.target.id==="w-gen"){S.draft.gen=e.target.value;genNames();}if(e.target.id==="w-ori"){S.draft.ori=e.target.value;genNames();}});


/* ---------- Campagnes ---------- */
if(!S.camps||!S.camps.length){S.camps=[{id:"c1",name:"Ma première campagne",created:Date.now(),log:[]}];S.campId="c1";}
if(!S.camps.some(c=>c.id===S.campId))S.campId=S.camps[0].id;
const CAMP=()=>S.camps.find(c=>c.id===S.campId);
function campLog(txt){const c=CAMP();c.log=c.log||[];c.log.unshift({at:Date.now(),txt});c.log=c.log.slice(0,100);}
function switchCamp(id){if(id===S.campId)return;const cur=CAMP();cur.scen=S.scen;const nx=S.camps.find(c=>c.id===id);if(!nx)return;
  S.scen=nx.scen||(()=>{const o={};SCENARIOS.forEach(s=>o[s.id]=newScenState(s));return o;})();nx.scen=null;S.campId=id;S.cur=null;save();}
function renderCampBar(){const c=CAMP();const plays=Object.entries(S.scen).filter(([k,v])=>v.finished).length;
  const who=[...new Set(Object.values(S.scen).flatMap(v=>v.party.map(p=>p.cid)))].map(id=>charById(id)?.n).filter(Boolean);
  $("#campBar").innerHTML=`<div class="cb-row"><span class="cb-l">Campagne</span>
    <select id="campSel" aria-label="Campagne en cours">${S.camps.map(x=>`<option value="${x.id}" ${x.id===S.campId?"selected":""}>${esc(x.name)}</option>`).join("")}</select>
    <span id="campZone"><button class="btn" id="campNew">Nouvelle campagne</button><button class="btn" id="campRen">Renommer</button>${S.camps.length>1?`<button class="btn warn" id="campDel">Supprimer</button>`:""}</span></div>
    <p class="cb-info">${plays} scénario${plays>1?"s":""} terminé${plays>1?"s":""}${who.length?` · investigateurs : ${who.map(esc).join(", ")}`:""}. Chaque campagne garde sa propre progression dans les scénarios et ses sauvegardes ; les personnages et leur évolution sont partagés.</p>
    ${c.log&&c.log.length?`<details class="saves"><summary>Journal de campagne (${c.log.length})</summary><ol class="hist">${c.log.map(x=>`<li><span class="hd">${fmtD(x.at)}</span>${esc(x.txt)}</li>`).join("")}</ol></details>`:""}`;}
const _renderHome=renderHome;renderHome=function(){_renderHome();renderCampBar();};
$("#campBar").addEventListener("change",e=>{if(e.target.id==="campSel"){switchCamp(e.target.value);renderHome();toast(`Campagne : ${CAMP().name}.`);}});
$("#campBar").addEventListener("click",e=>{const t=e.target,z=$("#campZone");
  const ask=(label,val,ok)=>{z.innerHTML=`<span class="confirm"><input id="campName" value="${esc(val)}" aria-label="${label}"><button class="btn prim" id="campOk">${label}</button><button class="btn" id="campNo">Annuler</button></span>`;$("#campName").select();
    const go=()=>{const v=$("#campName").value.trim();if(v)ok(v);renderHome();};$("#campOk").onclick=go;$("#campName").onkeydown=ev=>{if(ev.key==="Enter")go();};$("#campNo").onclick=()=>renderHome();};
  if(t.id==="campNew")ask("Créer",`Campagne ${S.camps.length+1}`,v=>{const id="c"+Date.now().toString(36);const cur=CAMP();cur.scen=S.scen;
    const o={};SCENARIOS.forEach(s=>o[s.id]=newScenState(s));S.camps.push({id,name:v,created:Date.now(),log:[]});S.scen=o;S.campId=id;S.cur=null;campLog("Campagne créée");save();toast(`Campagne « ${v} » créée.`);});
  if(t.id==="campRen")ask("Renommer",CAMP().name,v=>{CAMP().name=v;save();});
  if(t.id==="campDel"){z.innerHTML=`<span class="confirm">Supprimer « ${esc(CAMP().name)} » et sa progression ? <button class="btn warn" id="campDelYes">Oui</button><button class="btn" id="campNo">Non</button></span>`;
    $("#campNo").onclick=()=>renderHome();$("#campDelYes").onclick=()=>{const id=S.campId;const nx=S.camps.find(c=>c.id!==id);S.camps=S.camps.filter(c=>c.id!==id);
      S.scen=nx.scen||(()=>{const o={};SCENARIOS.forEach(s=>o[s.id]=newScenState(s));return o;})();nx.scen=null;S.campId=nx.id;S.cur=null;save();renderHome();toast("Campagne supprimée.");};}
});

/* ---------- Exporter / importer un personnage ---------- */
let DL=null;(async()=>{try{if(window.claude&&claude.use)DL=await claude.use("downloads");}catch(e){}})();
const slug=s=>s.normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/[^a-zA-Z0-9]+/g,"-").replace(/^-|-$/g,"").toLowerCase();
async function exportChar(id){const c=charById(id);if(!c)return;
  const data=JSON.stringify({type:"ecran-gardien-personnage",version:1,exporte:new Date().toISOString(),personnage:{...c},progression:S.prog[id]||null},null,2);
  if(DL){try{await DL.save({filename:`${slug(c.n)}.json`,data});toast(`Fiche de ${c.n} enregistrée.`);return;}catch(e){if(e&&e.code==="cancelled")return;}}
  try{await navigator.clipboard.writeText(data);toast("Le téléchargement n'est pas disponible ici : la fiche est copiée dans le presse-papiers. Colle-la dans un fichier .json.");}
  catch(e){toast("Impossible d'exporter depuis cette page.");}}
function importChar(txt){let d;try{d=JSON.parse(txt);}catch(e){toast("Ce fichier n'est pas une fiche de personnage valide.");return;}
  if(!d||d.type!=="ecran-gardien-personnage"||!d.personnage||!d.personnage.n){toast("Ce fichier n'est pas une fiche exportée depuis l'Écran du Gardien.");return;}
  const c={...d.personnage,custom:true};const clash=charById(c.id);
  if(clash){const same=clash.n===c.n;if(same&&clash.custom){const i=S.chars.findIndex(x=>x.id===c.id);S.chars[i]=c;}else{c.id="c"+Date.now().toString(36);if(!clash.custom)c.n=c.n;S.chars.push(c);}}
  else S.chars.push(c);
  if(d.progression)S.prog[c.id]=d.progression;
  histAdd(c.id,"Fiche importée");save();renderHome();toast(`${c.n} a rejoint tes personnages.`);}
document.addEventListener("click",e=>{const x=e.target.closest("[data-export]");if(x)exportChar(x.dataset.export);});
$("#impFile").addEventListener("change",async e=>{const f=e.target.files[0];if(!f)return;importChar(await f.text());e.target.value="";});


