  if(t.id==="addPlayer"){promptInline($("#addPlayerZone"),"Ajouter","",v=>{const p=addPlayer(v);save();toast(`${p.name} ajouté.`);});return;}
  const nc=t.closest("[data-newchar]");if(nc){newDraft();S.draft.owner=nc.dataset.newchar;S.afterCreate=null;save();show("creer");window.scrollTo(0,0);return;}
