/* ---------- Journal de séance ---------- */
const JK={de:"Dés",san:"Santé mentale",test:"Tests",pv:"Blessures",scene:"Scènes",combat:"Combat",partie:"Partie"};
let jFilter="";
function jlog(txt,k,key){if(!S.cur||!ST())return;const st=ST();st.journal=st.journal||[];const now=Date.now();
  const last=st.journal[0];if(key&&last&&last.key===key&&now-last.at<20000){last.t=txt;last.at=now;}
  else{const sc=scenesOf(SC()).find(x=>x.id===st.scene);st.journal.unshift({at:now,t:txt,k:k||"partie",key:key||null,sc:sc?sc.t:""});st.journal=st.journal.slice(0,600);}
  save();renderJournal();}
function renderJournal(){const el=$("#jList");if(!el||!S.cur)return;const J=(ST().journal||[]).filter(x=>!jFilter||x.k===jFilter);
  $("#jFilters").innerHTML=`<button data-jf="" class="${jFilter?"":"on"}">Tout</button>`+Object.entries(JK).map(([k,n])=>`<button data-jf="${k}" class="${jFilter===k?"on":""}">${n}</button>`).join("");
  el.innerHTML=J.length?J.slice(0,250).map(x=>`<li class="jk-${x.k}"><span class="jt">${new Date(x.at).toLocaleTimeString("fr-FR",{hour:"2-digit",minute:"2-digit"})}</span><span class="jx">${esc(x.t)}</span></li>`).join(""):`<li class="jempty">Rien pour l'instant. Les jets, pertes de SAN, blessures et changements de scène s'inscrivent ici.</li>`;}
$("#jFilters").addEventListener("click",e=>{const b=e.target.closest("[data-jf]");if(!b)return;jFilter=b.dataset.jf;renderJournal();});
$("#jCopy").onclick=async()=>{const J=(ST().journal||[]).slice().reverse();const txt=`Journal · ${SC().t}\n`+J.map(x=>`${new Date(x.at).toLocaleString("fr-FR",{day:"2-digit",month:"2-digit",hour:"2-digit",minute:"2-digit"})} [${JK[x.k]||x.k}] ${x.t}`).join("\n");
  try{await navigator.clipboard.writeText(txt);toast("Journal copié.");}catch(e){toast("Copie refusée par le navigateur.");}};
$("#jToNotes").onclick=()=>{const st=ST();const J=(st.journal||[]).slice(0,30).reverse();st.notes=(st.notes?st.notes+"\n\n":"")+J.map(x=>`- ${x.t}`).join("\n");$("#notes").value=st.notes;save();toast("30 dernières lignes ajoutées aux notes.");};
if(false)$("#qaJournal").onclick=()=>{$("#jPanel").scrollIntoView({behavior:"smooth",block:"start"});};
/* branchements */
const _showRes=showRes;showRes=function(...a){_showRes(...a);if(a[4]&&!PICK_BUSY)jlog(a[4],/^SAN/.test(a[4])?"san":"de");};
const _go=go;go=function(id,noMove){const st=ST();const before=st.scene;_go(id,noMove);if(id!==before||!noMove){ensureGroups();const g=grpOf(st.active);jlog(`${st.groups.length>1?g.name+" → ":"Scène : "}${sceneName(id)}`,"scene");}};
$("#invView").addEventListener("click",e=>{const b=e.target.closest("button[data-k]");if(!b)return;const sl=ST().party[+b.dataset.i];if(!sl)return;const c=charById(sl.cid),k=b.dataset.k,lab={pv:"PV",san:"SAN",chance:"Chance",pm:"PM"}[k];
  const base=sl["_j"+k]&&Date.now()-sl["_j"+k].at<20000?sl["_j"+k].from:sl[k]-(+b.dataset.d);sl["_j"+k]={from:base,at:Date.now()};
  jlog(`${c.n} : ${lab} ${base} → ${sl[k]}`,k==="san"?"san":k==="pv"?"pv":"partie",`${sl.cid}-${k}`);});
$("#invView").addEventListener("change",e=>{if(e.target.tagName!=="SELECT")return;const sl=ST().party[e.target.dataset.i];if(sl)jlog(`${charById(sl.cid).n} : ${STATES.find(x=>x[0]===sl.state)[1].toLowerCase()}`,"pv");});
const _ga=groupAct;groupAct=function(e){const t=e.target;const mv=t.closest("[data-mv]"),sp=t.closest("[data-split]"),mg=t.closest("[data-merge]");const r=_ga(e);
  if(r){if(sp)jlog("Le groupe se sépare","scene");if(mg)jlog("Les groupes se réunissent","scene");if(mv){const sl=ST().party.find(x=>x.cid===mv.dataset.mv);jlog(`${charById(sl.cid).n} rejoint ${grpOf(sl.grp).name}`,"scene");}}return r;};
const _sc=startCombat;startCombat=function(){_sc();const C=cbt();if(C.on)jlog(`Combat : ${C.roster.map(r=>r.name).join(", ")}`,"combat");};
document.addEventListener("click",e=>{if(e.target.id==="cbtEndYes")jlog("Fin du combat","combat");if(e.target.id==="markDone"&&ST().done[ST().scene])jlog(`Scène jouée : ${sceneName(ST().scene)}`,"scene");});
const _ss=saveSnapshot;saveSnapshot=async function(n,q){await _ss(n,q);jlog(`Sauvegarde : ${n||"Sauvegarde"}`,"partie");};

/* ---------- Jets ciblés depuis le scénario ---------- */
let PICK=null,PICK_BUSY=false;
const CHARS_K=["FOR","CON","TAI","DEX","APP","INT","POU","ÉDU"];
const SK_ALIAS={"trouver objet caché":["toc"],"latin":["langues (latin)"],"chimie":["sciences (chimie)"],"biologie":["sciences (biologie)"],"dessin":["arts et métiers"]};
function valFor(c,sl,label){const L=label.toLowerCase();
  if(L==="chance")return {v:sl.chance,sk:null};
  const ck=CHARS_K.find(k=>k.toLowerCase()===L);if(ck)return {v:carOf(c)[ck]||null,sk:null,car:ck};
  const list=allSkillsOf(c);const names=[L].concat(SK_ALIAS[L]||[]);
  let m=list.find(([n])=>names.includes(n.toLowerCase()))||list.find(([n])=>names.some(x=>n.toLowerCase().includes(x)||x.includes(n.toLowerCase())));
  if(m)return {v:m[1],sk:m[0]};
  if(L==="esquive")return {v:Math.floor(c.dex/2),sk:"Esquive"};
  const b=SKILLS.find(s=>s[0].toLowerCase()===L);if(b&&typeof b[1]==="number")return {v:b[1],sk:b[0],base:true};
  return {v:null,sk:label};}
function openPick(kind,label,val){if(!S.cur)return;const st=ST();ensureGroups();
  const alive=st.party.filter(sl=>sl.state!=="mort");
  PICK={kind,label,val,res:null,sel:new Set(alive.filter(sl=>sl.grp===st.active).map(sl=>sl.cid)),vals:{},B:0,M:0};
  if(kind==="dmg")PICK.sel=new Set();renderPick();$("#pick").hidden=false;}
function renderPick(){const P=PICK,st=ST();const title=P.kind==="san"?`SAN · ${P.label}`:P.kind==="dmg"?`${P.label}`:`Test de ${P.label}`;
  const rows=st.party.map(sl=>{const c=charById(sl.cid);const g=grpOf(sl.grp)||{col:0};const on=P.sel.has(sl.cid);const dead=sl.state==="mort";
    let extra="";if(P.kind==="test"){const f=valFor(c,sl,P.label);const v=P.vals[sl.cid]??f.v;extra=`<input type="number" min="1" max="99" class="pv-in" id="pv-${sl.cid}" data-pv="${sl.cid}" value="${v??""}" placeholder="?" aria-label="Valeur de ${esc(c.n)}">`;}
    if(P.kind==="san")extra=`<span class="pv-s">SAN ${sl.san}</span>`;if(P.kind==="dmg")extra=`<span class="pv-s">PV ${sl.pv}/${c.pv}</span>`;
    return `<label class="pk ${on?"on":""} ${dead?"dead":""}">${head(sl,g)}<input type="checkbox" data-pk="${sl.cid}" ${on?"checked":""} ${dead?"disabled":""}><span class="pn">${esc(c.n)}${sl.player?` <span class="mut">${esc(sl.player)}</span>`:""}</span>${extra}</label>`;}).join("");
  const res=P.res?`<ul class="pres">${P.res.map(r=>`<li class="${r.cls}"><b>${esc(r.n)}</b> ${esc(r.txt)}</li>`).join("")}</ul>`:"";
  $("#pickBox").innerHTML=`<div class="pk-head"><span class="gm-eyebrow">${P.kind==="san"?"Test de Santé mentale":P.kind==="dmg"?"Dégâts":"Test de compétence"}</span><h3>${esc(title)}</h3>
    ${P.kind==="san"?`<p class="mut">Réussite : −${esc(P.val.split("/")[0])} · échec : −${esc(P.val.split("/")[1])}. La perte est retirée automatiquement.</p>`:P.kind==="dmg"?`<p class="mut">${esc(P.val)} par cible, retirés des PV avec la règle de blessure grave.</p>`:`<p class="mut">Valeur trouvée sur la fiche, modifiable. Une réussite coche la compétence pour la progression.</p>`}</div>
    ${P.res?res:`<div class="pk-all"><button class="lnk" data-pkall="1">Tout le groupe suivi</button> · <button class="lnk" data-pkall="2">Tous</button> · <button class="lnk" data-pkall="0">Aucun</button></div><div class="pk-list">${rows}</div>
    ${P.kind==="test"?`<div class="dice-row"><span class="bm"><span class="g">Bonus</span><button data-pbm="B" data-d="-1" aria-label="Moins de bonus">−</button><span class="c">${P.B}</span><button data-pbm="B" data-d="1" aria-label="Plus de bonus">+</button></span><span class="bm"><span class="r">Malus</span><button data-pbm="M" data-d="-1" aria-label="Moins de malus">−</button><span class="c">${P.M}</span><button data-pbm="M" data-d="1" aria-label="Plus de malus">+</button></span></div>`:""}`}
    <div class="addrow">${P.res?`<button class="btn prim" id="pkClose">Fermer</button><button class="btn" id="pkAgain">Relancer pour d'autres</button>`:`<button class="btn prim" id="pkGo" ${P.sel.size||P.kind==="dmg"?"":"disabled"}>${P.kind==="dmg"&&!P.sel.size?"Lancer sans cible":"Lancer les dés"}</button><button class="btn" id="pkClose">Annuler</button>`}</div>`;}
function applyDamage(sl,v){const c=charById(sl.cid),max=c.pv,was=sl.state;sl.pv=Math.max(0,sl.pv-v);let note="";
  if(v>=max){sl.state="mort";sl.pv=0;note="coup égal ou supérieur à ses PV max : mort (p. 20)";}
  else if(v>=Math.ceil(max/2)){if(sl.pv===0){sl.state="mour";note="blessure grave et 0 PV : mourant, test de CON chaque round (p. 20)";}else{sl.state="bless";note="blessure grave : test de CON, sinon inconscient (p. 20)";}}
  else if(sl.pv===0&&was==="bless"){sl.state="mour";note="0 PV avec blessure grave : mourant (p. 20)";}
  else if(sl.pv===0){sl.state="incon";note="0 PV : inconscient (p. 20)";}
  if(sl.state!==was)histAdd(sl.cid,`${SC().t} : ${STATES.find(x=>x[0]===sl.state)[1].toLowerCase()}`);return note;}
function rollPick(){const P=PICK,st=ST();const res=[];PICK_BUSY=true;
  const targets=st.party.filter(sl=>P.sel.has(sl.cid));
  if(P.kind==="dmg"&&!targets.length){const x=rollFormula(P.val);res.push({n:P.label,txt:`${P.val} = ${x.tot}`,cls:"bad"});jlog(`${P.label} : ${P.val} = ${x.tot}`,"pv");}
  targets.forEach(sl=>{const c=charById(sl.cid);
    if(P.kind==="san"){const [a,b]=P.val.split("/");const x=d100(0,0);const ok=x.r<=sl.san;const f=ok?a:b;const loss=/D/i.test(f)?Math.max(0,rollFormula(f).tot):+f;const from=sl.san;sl.san=Math.max(0,sl.san-loss);
      let txt=`jet ${x.r} sur ${from} : ${ok?"réussi":"raté"}, −${loss} SAN (${from} → ${sl.san})`;let cls=ok?"ok":"bad";
      if(!ok&&loss>=5){const int=carOf(c).INT;if(int){const y=d100(0,0);if(y.r<=int){sl.state="ftemp";const fr=1+Math.floor(Math.random()*10),rd=1+Math.floor(Math.random()*10),hh=1+Math.floor(Math.random()*10);
          txt+=`. Test d'INT ${y.r} sur ${int} réussi : folie temporaire ${hh} h, folie passagère « ${FOLIES[fr-1].split(" :")[0]} » ${rd} rounds`;histAdd(sl.cid,`${SC().t} : folie temporaire (${P.label})`);cls="mad";}
          else txt+=`. Test d'INT ${y.r} sur ${int} raté : il reste sain d'esprit pour l'instant`;}
        else txt+=". Perte de 5 ou plus : fais un test d'INT (réussi = folie temporaire 1D10 h)";}
      res.push({n:c.n,txt,cls});jlog(`${c.n} · SAN ${P.label} : ${txt}`,"san");}
    if(P.kind==="test"){const f=valFor(c,sl,P.label);const v=+(P.vals[sl.cid]??f.v)||0;if(!v){res.push({n:c.n,txt:"valeur manquante, pas de jet",cls:""});return;}
      const x=d100(P.B,P.M),L=level(x.r,v);const ok=L[0]!=="fail";let txt=`${x.r} sur ${v} : ${L[1].toLowerCase()}`;
      if(ok&&f.sk&&!CHARS_K.includes(P.label.toUpperCase())&&P.label!=="Chance"){const p=P_(sl.cid);if(!p.checks.includes(f.sk)){p.checks.push(f.sk);txt+=` · ${f.sk} cochée`;}}
      res.push({n:c.n,txt,cls:ok?"ok":"bad"});jlog(`${c.n} · ${P.label} : ${txt}`,"test");}
    if(P.kind==="dmg"){const x=rollFormula(P.val);const v=Math.max(0,x.tot);const from=sl.pv;const note=applyDamage(sl,v);const txt=`${P.val} = ${v} dégâts (PV ${from} → ${sl.pv})${note?" · "+note:""}`;
      res.push({n:c.n,txt,cls:"bad"});jlog(`${c.n} · ${P.label} : ${txt}`,"pv");}
  });
  PICK_BUSY=false;P.res=res;save();renderPick();renderInv();renderNav();
  const good=res.filter(r=>r.cls==="ok").length,bad=res.filter(r=>r.cls==="bad"||r.cls==="mad").length;
  const fx=res.some(r=>r.cls==="mad")?"fumble":good&&!bad?"good":bad&&!good?"bad":null;
  if(fx&&!matchMedia("(prefers-reduced-motion: reduce)").matches){const F=$("#flash");F.hidden=false;F.className="flash on-"+fx;setTimeout(()=>{F.hidden=true;F.className="flash";},1200);}}
