/* ---------- Lexique au survol ---------- */
const GLOSS=GRIMOIRE_DATA.GLOSS;
let GL_RE=new RegExp("(?<![\\p{L}\\d/])("+GLOSS.map((g,i)=>`(?<g${i}>${g[3]})`).join("|")+")(?![\\p{L}\\d])","gu");
const GL_SKIP="input,textarea,select,option,script,style,svg,.gl,#glTip,.glos,code,pre,.tm-title,.jx,#nlog,.cbox,.sktab td:first-child,.dice2 .result,.d2-tabs,.d2-go,.d2-dice,.quick,.log";
function glWrap(root){if(!root||root.nodeType!==1)return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>{const p=n.parentElement;if(!p||p.closest(GL_SKIP)||!n.nodeValue.trim())return NodeFilter.FILTER_REJECT;return NodeFilter.FILTER_ACCEPT;}});
  const nodes=[];while(w.nextNode())nodes.push(w.currentNode);
  nodes.forEach(n=>{const t=n.nodeValue;GL_RE.lastIndex=0;if(!GL_RE.test(t))return;GL_RE.lastIndex=0;const f=document.createDocumentFragment();let last=0,m;
    while((m=GL_RE.exec(t))){const i=Object.keys(m.groups).find(k=>m.groups[k]!==undefined);f.append(t.slice(last,m.index));const a=document.createElement("abbr");a.className="gl";a.dataset.gl=i.slice(1);a.tabIndex=0;a.textContent=m[0];f.append(a);last=m.index+m[0].length;}
    f.append(t.slice(last));n.replaceWith(f);});}
let glT=null;const glMO=new MutationObserver(()=>{clearTimeout(glT);glT=setTimeout(()=>{glMO.disconnect();["#vPlay","#vRules","#vCreate","#vSetup","#pick","#dicePanel","#gMenu"].forEach(s=>glWrap($(s)));glObserve();},60);});
function glObserve(){["#vPlay","#vRules","#vCreate","#vSetup","#pick","#dicePanel"].forEach(s=>{const el=$(s);if(el)glMO.observe(el,{childList:true,subtree:true,characterData:true});});}
const tip=document.createElement("div");tip.id="glTip";tip.hidden=true;tip.setAttribute("role","tooltip");document.body.appendChild(tip);
function glShow(a){const g=GLOSS[+a.dataset.gl];if(!g)return;tip.innerHTML=`<b>${g[1]}</b><span>${g[2]}</span>`;tip.hidden=false;
  const r=a.getBoundingClientRect(),tw=tip.offsetWidth,th=tip.offsetHeight;let x=Math.min(Math.max(8,r.left+r.width/2-tw/2),innerWidth-tw-8);let y=r.top-th-8;if(y<8)y=r.bottom+8;tip.style.left=x+"px";tip.style.top=y+"px";}
const glHide=()=>{tip.hidden=true;};
document.addEventListener("mouseover",e=>{const a=e.target.closest(".gl");if(a)glShow(a);else if(!e.target.closest("#glTip"))glHide();});
document.addEventListener("focusin",e=>{const a=e.target.closest(".gl");if(a)glShow(a);});document.addEventListener("focusout",e=>{if(e.target.closest(".gl"))glHide();});
document.addEventListener("scroll",glHide,true);
