/* ================= Langue de l'interface : français / English ================= */
const I18N=GRIMOIRE_DATA.I18N;
const I18N_PAT=I18N.pat.map(([r,s])=>{try{return [new RegExp(r),s]}catch(e){return null}}).filter(Boolean);
const SK_FR2EN=I18N.sk, SK_EN2FR=Object.fromEntries(Object.entries(SK_FR2EN).filter(([f])=>f!=="TOC").map(([f,e])=>[e.toLowerCase(),f]));
let LANG=(()=>{try{return localStorage.getItem("gardien-lang")||"fr"}catch(e){return "fr"}})();
const AMB_EN={};
function trS(s){if(!s)return s;const lead=s.match(/^\s*/)[0],trail=s.match(/\s*$/)[0];const t=s.trim();if(!t)return s;
  let r=I18N.ui[t];
  if(r==null&&SK_FR2EN[t])r=SK_FR2EN[t];
  if(r==null){for(const [re,rep] of I18N_PAT){if(re.test(t)){r=t.replace(re,rep);break;}}}
  if(r==null){let m=t.match(/^(.+?)\s(\d{1,3})(\s?%)?$/);if(m&&SK_FR2EN[m[1]])r=`${SK_FR2EN[m[1]]} ${m[2]}${m[3]||""}`;}
  if(r==null){let m=t.match(/^Test\s+(.+?)(\s·\s.*)?$/);if(m){const n=SK_FR2EN[m[1]]||I18N.ui[m[1]];if(n)r=`${n}${m[2]||""}`;}}
  if(r==null){let m=t.match(/^SAN\s+(.+?)\s·\s(.+)$/);if(m)r=`SAN ${I18N.ui[m[1]]||m[1]} · ${m[2]}`;}
  if(r==null){let m=t.match(/^♪\s*Ambiance\s*:\s*(.+)$/);if(m)r="♪ Ambience: "+m[1].split(" + ").map(x=>I18N.ui[x]||x).join(" + ");}
  if(r==null){let m=t.match(/^◗\s*(.+)$/);if(m&&I18N.ui[m[1]])r="◗ "+I18N.ui[m[1]];}
  if(r==null){let m=t.match(/^(.+?)\s·\s(.+)$/);if(m&&(I18N.ui[m[1]]||SK_FR2EN[m[1]]))r=`${I18N.ui[m[1]]||SK_FR2EN[m[1]]} · ${m[2]}`;}
  if(r==null){let m=t.match(/^Test de (.+)$/);if(m){const n=SK_FR2EN[m[1]]||I18N.ui[m[1]];if(n)r=`${n} roll`;}}
  if(r==null){let m=t.match(/^Livre Deux,\s*(p\..*)$/);if(m)r="Book Two, "+m[1];}
  if(r==null&&/^PV \d/.test(t))r=t.replace(/^PV /,"HP ").replace(/ · Esq\. /," · Dodge ");
  if(r==null)return s;return lead+r+trail;}
const I18N_SKIP="script,style,textarea,input,[data-noi18n],#glTip";
const I18N_ATTR=["title","placeholder","aria-label"];
let i18nBusy=false;
function i18nNode(root){if(!root)return;
  const doText=n=>{const p=n.parentElement;if(!p||p.closest(I18N_SKIP))return;
    if(LANG==="en"){const src=n.__fr!=null&&n.nodeValue===n.__en?n.__fr:n.nodeValue;const tr=trS(src);if(tr!==src){n.__fr=src;n.__en=tr;if(n.nodeValue!==tr)n.nodeValue=tr;}}
    else if(n.__fr!=null&&n.nodeValue===n.__en){n.nodeValue=n.__fr;n.__fr=null;}};
  const doEl=el=>{if(el.closest&&el.closest(I18N_SKIP))return;I18N_ATTR.forEach(a=>{if(!el.hasAttribute||!el.hasAttribute(a))return;const k="__fr_"+a;const v=el.getAttribute(a);
    if(LANG==="en"){const src=el[k]!=null&&v===el["__en_"+a]?el[k]:v;const tr=trS(src);if(tr!==src){el[k]=src;el["__en_"+a]=tr;if(v!==tr)el.setAttribute(a,tr);}}
    else if(el[k]!=null&&v===el["__en_"+a]){el.setAttribute(a,el[k]);el[k]=null;}});};
  if(root.nodeType===3){doText(root);return;}
  if(root.nodeType!==1)return;doEl(root);
  const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT);while(w.nextNode()){const n=w.currentNode;if(n.nodeType===3)doText(n);else doEl(n);}}
function i18nAll(){i18nBusy=true;i18nNode(document.body);document.title=LANG==="en"?"Keeper's Screen":"Écran du Gardien";document.documentElement.lang=LANG;i18nBusy=false;}
const i18nMO=new MutationObserver(ms=>{if(i18nBusy||LANG!=="en")return;i18nBusy=true;
  ms.forEach(m=>{if(m.type==="characterData")i18nNode(m.target);else if(m.type==="attributes")i18nNode(m.target);else m.addedNodes.forEach(n=>i18nNode(n));});
  i18nBusy=false;});
i18nMO.observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:I18N_ATTR});

